# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_flect_a import L,H
F=L+[['英语 flex 的来源分析','可追到拉丁 flexus；也有认为英语从 flexible 逆构的分析'],['英语 flex','弯曲、绷紧肌肉；后来也说展示、炫耀']]
FB=L+[['拉丁 flexibilis → 法语 flexible／直接借入英语','能够弯曲、容易顺应'],['英语 flexible','柔韧的；能调整的、灵活的']]
IB=L+[['拉丁 in- + flexibilis → inflexibilis','不 + 可弯曲的 → 不可弯曲、不易改变'],['中古法语 inflexible → 英语 inflexible','僵硬的；不肯变通的']]
WB=[
E('flex','/fleks/','弯曲；绷紧肌肉；展示、炫耀；弯曲动作；软电线〔英〕','手臂一弯，肌肉一绷，让人看见力量；这个画面后来也能说炫耀钱、能力或地位。','最终接拉丁 flexus“弯曲的”。动词有直接借入和从 flexible 逆构两种分析；软电线义则缩自 flexible cord。',F,'flex your muscles 可以真的绷起肌肉，也可以比喻展示实力。网络里 a flex 常指一件拿来炫耀的事。英式语境 the lamp’s flex 指灯的软电线，是“柔性电线”的简称，不是电线正在炫耀。','flex a joint；flex your muscles；a big flex；electrical flex。','flex 强调弯动、绷紧或展示；stretch 主要说伸展。两种动作可能都出现在活动身体时，但不是同一动作。',('The thin strip flexes when you press it.','按下去时，这根细条会弯曲。'),('Posting the receipt felt like a flex.','把收据晒出来，看起来像是在炫耀。'),('The lamp’s flex was tucked behind the desk.','灯的软电线被收在书桌后面。'),sources=['https://www.merriam-webster.com/dictionary/flex','https://www.etymonline.com/word/flex']),
E('flexible','/ˈfleksəbəl/','柔韧的；灵活的；可调整的','像一根能弯而不轻易断的软管，也像一个能随实际情况调整的计划。','词形可看作 flex- + -ible；历史上拉丁 flexibilis 已是形容词，经法语或直接进入英语。',FB,'flexible material 是材料能弯；a flexible schedule 是时间可以商量调整；a flexible person 愿意换一种办法。共同点是“不被一个固定形状锁死”。它不等于没有规则，而是规则或做法留有调整空间。','flexible hours；a flexible approach；be flexible about dates。','flexible 侧重能改变形状或安排；elastic 更强调受力变形后能恢复。会弯的材料不一定都有良好弹性。',('The hose is flexible enough to fit around the corner.','这根软管够柔韧，能绕过拐角。'),('We can be flexible about the start date.','开始日期可以灵活安排。'),sources=['https://www.etymonline.com/word/flexible','https://en.wiktionary.org/wiki/flexible']),
E('flexibility','/ˌfleksɪˈbɪlɪti/','柔韧性；灵活性；调整余地','不是只有一条死路，而是还有几种可以转弯的选择。','现代与 flexible + -ity 对应；历史名词接晚期拉丁 flexibilitas、法语 flexibilité。',L+[['拉丁 flexibilis → 晚期拉丁 flexibilitas','可弯曲的 → 可弯曲、可顺应的性质'],['法语 flexibilité → 英语 flexibility','柔韧性、灵活性']],'材料的 flexibility 说能弯到什么程度；安排的 flexibility 说能否根据需要改变。have the flexibility to work from home 是有这种选择余地，不代表每天都必须在家工作。这个名词把“能够调整”当作一种资源或性质来谈。','give someone flexibility；flexibility in scheduling；the flexibility to do something。','flexibility 是灵活性；instability 是不稳定。能按需调整，不等于无缘无故乱变。',('The new system gives teachers more flexibility.','新制度给教师更多调整空间。'),('We tested the flexibility of the material.','我们测试了这种材料的柔韧性。'),sources=['https://www.etymonline.com/word/flexibility','https://en.wiktionary.org/wiki/flexibility']),
E('flexibly','/ˈfleksəbli/','灵活地；可变通地','目标仍然在，走法却可以根据情况拐个弯。','flexible + -ly，去掉末尾 e 后形成 -ibly。',H(FB,'英语 flexible → flexibly','灵活的 → 灵活地'),'apply a rule flexibly 是考虑具体情况再应用规则；work flexibly 常说时间、地点或安排可以调整。这个副词关注事情怎么做，而不是把某个人贴上“灵活”的标签。','work flexibly；respond flexibly；apply something flexibly。','flexibly 不等于 randomly。灵活变化通常是在回应需要，随机变化没有这种必然联系。',('The team responded flexibly when the schedule changed.','日程变化后，团队灵活调整了做法。'),('The policy allows staff to work more flexibly.','这项政策让员工能更灵活地安排工作。'),sources=['https://en.wiktionary.org/wiki/flexibly','https://dictionary.cambridge.org/dictionary/english/flexibly']),
E('inflexible','/ɪnˈfleksəbəl/','不易弯曲的；僵硬的；不肯变通的','一根硬条怎么掰都不让步；一种做法也可能同样死板。','否定 in- 与 flexible 同族；历史上拉丁 inflexibilis 经法语借入英语。',IB,'an inflexible material 不容易弯；an inflexible rule 无论情况怎样都难以调整；an inflexible manager 不愿改变安排。它通常带有“变通不够”的评价，但在谈材料时可以只是客观性质。','an inflexible attitude；inflexible working hours；be inflexible about。','inflexible 说不肯或不能调整；firm 可以只是立场坚定。原则坚定的人，执行方法仍可灵活。',('The old timetable was too inflexible for working parents.','旧时间表太死板，不适合有工作的家长。'),('He remained inflexible about the deadline.','他始终不肯调整截止日期。'),sources=['https://www.etymonline.com/word/inflexible','https://en.wiktionary.org/wiki/inflexible']),
E('inflexibility','/ɪnˌfleksəˈbɪlɪti/','僵硬；缺少变通；不灵活','需要转弯时，制度或态度却卡在那里动不了。','与 inflexible + -ity 对应；历史上也有法语 inflexibilité 的借入链，不必从英语 flexibility 再加 in- 倒推。',L+[['拉丁 inflexibilis 及其法语词族','不能弯、不能变通'],['法语 inflexibilité → 英语 inflexibility','僵硬、不灵活这一性质']],'the inflexibility of the system 可以指改一个小安排都办不到。批评某人的 inflexibility，通常是在说他面对新信息仍不肯调整，而不是说他身体不够柔韧；后者要靠运动、材料等语境判断。','the inflexibility of a system；criticize someone’s inflexibility。','inflexibility 强调缺少调整空间；consistency 强调前后原则一致，不天然是缺点。',('The inflexibility of the booking system frustrated customers.','预订系统无法灵活调整，让顾客很不满。'),('Her inflexibility made compromise difficult.','她不肯变通，使妥协变得困难。'),sources=['https://en.wiktionary.org/wiki/inflexibility','https://www.collinsdictionary.com/dictionary/english/inflexibility']),
E('inflexibly','/ɪnˈfleksəbli/','不肯变通地；僵硬地','别人把新情况摆出来，回答还是原来那一句。','inflexible + -ly，对应“不灵活地做某事”。',H(IB,'英语 inflexible → inflexibly','不肯变通的 → 不肯变通地'),'apply a policy inflexibly 是不顾具体情况，照同一种方式执行。remain inflexibly opposed 则是一直坚决反对、毫不让步。语气要看语境：可能批评死板，也可能强调无法动摇。','apply rules inflexibly；remain inflexibly opposed to。','inflexibly 常强调不能改变；carefully 只强调谨慎。谨慎执行也可以允许合理变通。',('The rule was applied inflexibly to every case.','这条规则被毫无变通地用于每一个案例。'),('She remained inflexibly opposed to the proposal.','她始终毫不让步地反对这项提议。'),sources=['https://dictionary.cambridge.org/dictionary/english/inflexibly','https://www.collinsdictionary.com/dictionary/english/inflexibly']),
E('flexed','/flekst/','弯曲的；绷紧的；flex 的过去式、过去分词','手肘已经弯起，或肌肉已经收紧，形成一个动作后的状态。','flex + -ed；/s/ 后的 -ed 读 /t/，整个词是一音节 /flekst/。',H(F,'英语 flex → flexed','弯动、绷紧 → 弯了、绷紧了'),'a flexed knee 是弯着的膝关节；flexed muscles 是收紧的肌肉。He flexed his authority 也可比喻他展示或运用了权力。别把所有 flexed 都翻成“弯曲过的材料”，要看动作对象。','a flexed joint；flexed muscles；flexed his authority。','flexed 描述动作或状态；flexible 描述弯曲、调整的能力。能弯的东西此刻不一定正在弯。',('The model shows the elbow in a flexed position.','模型展示了肘关节弯曲时的位置。'),('He flexed his fingers before returning to the keyboard.','他活动了一下手指，又把手放回键盘。'),sources=['https://en.wiktionary.org/wiki/flexed','https://www.merriam-webster.com/dictionary/flex']),
E('flexing','/ˈfleksɪŋ/','弯动；绷肌肉；展示、炫耀','反复弯一弯、绷一绷；在社交语境里，也可以是把自己的优势摆出来。','flex + -ing，可表示进行中的动作，也可把这个动作当名词说。',H(F,'英语 flex → flexing','弯动、展示 → 弯动或展示这一行为'),'repeated flexing 是材料反复受弯；muscle flexing 是收紧肌肉来展示。社交媒体里的 flexing 常指晒财富、能力或地位，语气可能调侃，也可能批评。先看对象，再决定该译“弯”还是“炫”。','repeated flexing；muscle flexing；flexing online。','flexing 可以只是一时展示；training 是有安排的训练，二者并不等同。',('Repeated flexing damaged the thin cable.','反复弯折损坏了那根细电线。'),('The post was more about flexing than sharing useful advice.','那条帖子更像是在炫耀，而不是分享有用建议。'),sources=['https://en.wiktionary.org/wiki/flexing','https://www.merriam-webster.com/dictionary/flex']),
E('flexion','/ˈflekʃən/','屈曲；弯曲动作或状态','把伸开的关节弯起来，例如让前臂靠近上臂。','接拉丁 flexio“弯曲”，可能经法语进入英语；现代可识别 flex- 与名词后缀。',L+[['拉丁 flexio → 英语 flexion，可能经法语','弯曲这一动作或状态']],'解剖学里的 flexion 常说关节屈曲，例如弯肘；与 extension 伸展相对。具体方向要结合关节的定义。旧语言学文献也会用 flexion 说词形变化，现代普通英语学习材料更常见 inflection。','elbow flexion；knee flexion；flexion and extension。','flexion 说实际弯曲动作或状态；flexibility 说能弯、能调整的程度。',('The diagram compares elbow flexion with elbow extension.','图示对比了肘关节屈曲和伸展。'),('The report records the range of knee flexion.','报告记录了膝关节屈曲的活动范围。'),sources=['https://en.wiktionary.org/wiki/flexion','https://openstax.org/books/anatomy-and-physiology/pages/9-5-types-of-body-movements']),
E('flexor','英 /ˈfleksə/；美 /ˈfleksər/','屈肌','负责把关节弯起来的肌肉，像一根向里拉的绳子。','新拉丁 flexor 是接 flectere“弯曲”的施事名词，再借入英语；不是任意肌肉都叫 flexor。',L+[['新拉丁 flexor → 英语 flexor','使关节屈曲的肌肉']],'a finger flexor 帮助手指弯曲；hip flexors 参与髋关节屈曲。肌肉常按作用命名，因此这个词告诉你它主要做什么，不是单凭名字给出精确位置。具体肌肉的作用还与姿势和关节有关。','a flexor muscle；finger flexors；hip flexors。','flexor 主要使关节屈曲；extensor 主要使关节伸展。它们是按动作功能命名的相对概念。',('The lesson identifies the main flexor muscles of the fingers.','这节课辨认了手指的主要屈肌。'),('The diagram labels a flexor and an extensor.','图中标出了一块屈肌和一块伸肌。'),sources=['https://en.wiktionary.org/wiki/flexor','https://openstax.org/books/anatomy-and-physiology/pages/11-2-naming-skeletal-muscles']),
E('flexile','英 /ˈfleksaɪl/；美 /ˈfleksɪl/','柔韧的；可弯曲的〔少见、偏文学〕','细枝轻轻一推便弯过去，没有僵硬地顶住。','来自拉丁 flexilis，经其词干 flexil- 借入英语；与 flexible 是近义的同源旁支。',L+[['拉丁 flexilis → 英语 flexile','能够弯曲、柔韧的']],'flexile 在文学或较旧文字里可以形容细枝、身体等柔韧。现代日常交流通常直接用 flexible。认识这个词是为了读懂作者的文体，不必为了显得高级而替换所有 flexible。','a flexile stem；flexile limbs；flexile branches。','flexile 与 flexible 意义接近，区别主要在常见程度和文体；前者并不是“更灵活一级”。',('The poem describes the willow’s flexile branches.','诗中描写了柳树柔韧的枝条。'),('The old guide calls the young stem “flexile.”','那本旧指南把嫩茎形容为“柔韧可弯的”。'),sources=['https://www.etymonline.com/word/flexible','https://www.collinsdictionary.com/dictionary/english/flexile']),
]
